r"""Individually authored conditional calculations, proofs and counterexamples."""
from pathlib import Path
import json
questions=[]
def add(title,stem,solution,origin='Original problem',difficulty='Medium',result=None):
    questions.append(dict(id=f'SC{len(questions)+1:02}',title=title,stem=stem,solution=solution,origin=origin,difficulty=difficulty,result=result))

add('Unequal retained masses',r'Four atoms have weights $(1,2,3,4)$. Event $A$ contains atoms one and three; $B$ contains atoms one and two. Find both reversed conditionals and the conditional weight of each atom given $B$.',r'The total weight ten cancels in each ratio. The common intersection has weight one; $B$ has weight three and $A$ has weight four. Thus $P(A\mid B)=1/3$ and $P(B\mid A)=1/4$. Given $B$, the four atom weights become $(1/3,2/3,0,0)$. Counting two retained atoms as equally likely would give an incorrect answer because conditioning preserves their original weight ratio. The conditional weights sum to one and the two joint identities each recover original probability $1/10$.',result=['1/3','1/4'])
add('Reconstruct every cell',r'Given $P(B)=2/5$, $P(A\mid B)=3/4$, and $P(A\mid B^c)=1/6$, reconstruct all four joint cells, find $P(A)$, and decide whether $A,B$ are independent.',r'Multiply each conditional by its stratum mass. In the order both, A only, B only, neither, the cells are $3/10,1/10,1/10,1/2$. They are nonnegative and sum to one, so the data define a valid model. Summing the A row gives $P(A)=2/5$. Independence would require intersection $(2/5)(2/5)=4/25$, while the actual value is $3/10$. The events are dependent and positively associated. Equal marginals explain the equal reversed conditionals but do not imply independence.',result=['3/10','1/10','1/10','1/2'])
add('An impossible conditional specification',r'Can $P(A)=1/5$, $P(B)=3/5$, and $P(A\mid B)=1/2$ hold simultaneously? Give a precise reason.',r'The last two numbers force joint mass $P(A\cap B)=(3/5)(1/2)=3/10$. However an intersection is contained in A and cannot have probability greater than $P(A)=1/5$. Equivalently the A-only cell would be $1/5-3/10=-1/10$, violating nonnegativity. Therefore no probability model satisfies these premises. It is inappropriate to continue computing a reverse conditional from inconsistent data; the feasibility check must precede inference.',result='infeasible')
add('Sharp range of a conditional',r'If $P(A)=7/10$ and $P(B)=3/5$, determine the smallest and largest possible $P(A\mid B)$ and construct cells attaining each.',r'The joint mass x lies between $7/10+3/5-1=3/10$ and $3/5$. Dividing by $3/5$ gives the sharp interval $[1/2,1]$. At the lower endpoint the cells are $(3/10,2/5,3/10,0)$; at the upper endpoint they are $(3/5,1/10,0,3/10)$. Each construction is nonnegative and normalized, so both endpoints are attainable. The upper endpoint says B implies A almost surely; the lower endpoint makes the neither cell empty in probability.',difficulty='Hard',result=['1/2','1'])
add('Recover an unknown stratum weight',r'Events satisfy $P(A\mid B)=4/5$, $P(A\mid B^c)=1/5$, and $P(A)=1/2$. Find the unknown stratum weight $P(B)$ and the reversed conditional $P(B\mid A)$.',r'Let b be the unknown stratum mass. Total probability gives $1/2=(4/5)b+(1/5)(1-b)$, hence $b=1/2$. The joint mass is $b(4/5)=2/5$, and reversing the conditional gives $(2/5)/(1/2)=4/5$. The four cells are $(2/5,1/10,1/10,2/5)$, confirming feasibility. The equality of reversed conditionals is explained by equal marginals, not by an automatic symmetry of conditional probability. All denominators in this reconstructed model are positive.',result=['1/2','4/5'])
add('Equal reversed conditionals without equal marginals',r'For positive marginal probabilities, characterize when $P(A\mid B)=P(B\mid A)$. Can they be equal when the marginals differ?',r'Write x for the intersection. Equality is $x/b=x/a$, equivalent after multiplication by positive ab to $x(a-b)=0$. Therefore either x is zero or the marginals are equal. Positive-probability disjoint events supply unequal-marginal examples: take A mass $1/4$ and disjoint B mass $1/2$. Both conditionals are zero. Dividing one conditional by the other would wrongly discard this case because that step would divide by zero.',difficulty='Hard',result='x=0 or a=b')
add('Association changes in both directions',r'Assume positive marginals and $P(A\mid B)>P(A)$. Prove the corresponding strict inequality for $P(B\mid A)$, and identify the quantity that controls both signs.',r'The given inequality is $x/b>a$, which is equivalent to $x-ab>0$ because b is positive. Dividing that same inequality by a gives $x/a>b$, the desired $P(B\mid A)>P(B)$. More precisely the two differences are $(x-ab)/b$ and $(x-ab)/a$. Their magnitudes can differ but their signs agree. If one marginal is zero its corresponding conditional is undefined, so the positive-marginal premise cannot be dropped.',origin='Adapted proof structure: CMU Chapter 2, Exercise 2.8',difficulty='Hard',result='same sign')
add('A conditional union uses one universe',r'Inside a positive event $C$, suppose $P(A\mid C)=2/3$, $P(B\mid C)=1/2$, and $P(A\cap B\mid C)=1/3$. Find the conditional union, exactly one, and neither.',r'Apply inclusion-exclusion to the conditional probability measure. The union is $2/3+1/2-1/3=5/6$. Exactly one subtracts both copies of the intersection from the sum, giving $2/3+1/2-2/3=1/2$. Neither is the complement of the union, giving $1/6$. The both, A-only, B-only, neither cells within C are $(1/3,1/3,1/6,1/6)$. Their sum is one; mixing an unconditional intersection into this calculation would break the common universe.',result=['5/6','1/2','1/6'])
add('Implication in probability versus literal containment',r'Construct events with $P(A\mid B)=1$ but $B\not\subseteq A$ as sets. Explain why there is no contradiction.',r'Use three outcomes with weights $(1/2,1/2,0)$. Let A contain only outcome one, and let B contain outcomes one and three. Then $P(B)=1/2$ and $P(A\cap B)=1/2$, so the conditional is one. Nevertheless outcome three belongs to B but not A. The formula proves only $P(B\setminus A)=0$. It establishes almost-sure containment; literal containment follows only with additional support assumptions such as strictly positive weights on every finite outcome.',difficulty='Hard',result='null difference')
add('Nested information',r'For weights $(1,2,3,4,5)$, let $A=\{1,4\}$, $B=\{1,2,4\}$, and $C=\{1,2,3,4\}$. Verify the nested-conditioning identity numerically.',r'The total weight is fifteen, but ratios can use unnormalized weights. The intersection B with C is B, of weight seven; its intersection with A has weight five. Thus $P(A\mid B\cap C)=5/7$. Inside C, $P(A\cap B\mid C)=5/10$ and $P(B\mid C)=7/10$, whose ratio is again $5/7$. The cancellation is valid because both C and its intersection with B have positive mass. Averaging $P(A\mid B)$ and $P(A\mid C)$ would have no justification.',result='5/7')
add('A zero last factor is allowed',r'Suppose $P(A)=2/5$, $P(B\mid A)=3/4$, and $P(C\mid A\cap B)=0$. Find the triple probability and explain why the chain rule remains defined.',r'The prefix A has positive mass $2/5$, and the second prefix has mass $(2/5)(3/4)=3/10$. Both denominators used in the chain exist. The last conditional factor is zero, so the triple mass is zero. Positive final mass is not required; it is only a sufficient way of guaranteeing positive prefixes. If a further factor conditioned on the zero-mass triple were written, it would be undefined. A tree should stop that branch rather than multiply an undefined number by zero.',result='0')
add('Dropping history changes a joint answer',r'For independent fair bits let $A=\{X=1\}$, $B=\{Y=1\}$, and $C=\{X=Y\}$. Compare the correct chain product with the product that conditions C only on B.',r'The joint event is the single bit pair 11, so its mass is $1/4$. The full factors are $1/2,1/2,1$, giving $1/4$. Conditioning C only on B leaves two possibilities 01 and 11, so the abbreviated last factor is $1/2$ and the product becomes $1/8$. The error assumes that observing X adds no information after Y, which is false for the equality event. Pairwise independence of some event pairs does not license this history deletion.',difficulty='Hard',result=['1/4','1/8'])
add('Reverse a three-stage factorization',r'$P(A)=3/5$, $P(B\mid A)=1/2$, $P(C\mid A\cap B)=2/3$, $P(C)=2/5$, and $P(B\mid C)=3/4$. Determine $P(A\mid B\cap C)$ and state the consistency check.',r'The original chain fixes the triple mass at $(3/5)(1/2)(2/3)=1/5$. The reverse-order prefix has mass $P(B\cap C)=(2/5)(3/4)=3/10$. Dividing gives $P(A\mid B\cap C)=2/3$. The triple mass must not exceed either relevant prefix; indeed $1/5\le3/10$. The given quantities leave other joint cells unspecified, but they are compatible: choose AB-only and BC-only each $1/10$, A-only $3/10$, C-only $1/10$, and neither $1/5$.',difficulty='Hard',result='2/3')
add('Conditional paths with a stated Markov assumption',r'An initial bit is one with probability $2/5$. At each subsequent step, the next bit differs from the current bit with probability $1/3$, independently of earlier history given the current bit. Find the masses of 101 and 111 and their conditional proportions given these are the only retained paths.',r'The stated conditional-history property permits use of transition probabilities based on the current bit. Path 101 has mass $(2/5)(1/3)(1/3)=2/45$. Path 111 has mass $(2/5)(2/3)(2/3)=8/45$. The retained union is disjoint and has mass $10/45$. Dividing gives conditional proportions $1/5$ and $4/5$. The transition model was an explicit premise; without it, a marginal probability of changing at each step would not determine either path probability.',difficulty='Hard',result=['2/45','8/45','1/5'])
add('Minimum and maximum of two rolls',r'Two independent fair four-sided dice show X and Y. Given $\min(X,Y)=2$, determine the distribution of $\max(X,Y)$.',r'The condition retains ordered pairs $(2,2),(2,3),(3,2),(2,4),(4,2)$. They each had probability $1/16$, so the conditional universe has five equal atoms. The maximum is two in one atom, three in two atoms, and four in two atoms, giving probabilities $1/5,2/5,2/5$. A maximum of one is impossible under the condition. Counting unordered pairs as three equal alternatives would ignore that off-diagonal pairs represent two ordered outcomes.',origin='Completed written example: MIT 6.041SC Lecture 2, PDF page 1',result=['1/5','2/5','2/5'])
add('Sampling a specified pattern',r'An urn has four red and three blue objects. Find the probability of red-blue-red without replacement, then the probability of exactly two reds in three draws.',r'The specified path has probability $(4/7)(3/6)(3/5)=6/35$. There are three disjoint color-position patterns with two reds, all with the same numerator factors, so exactly two reds has probability $18/35$. Unordered counting confirms $\binom42\binom31/\binom73=18/35$. The conditional probability of a second red after a first red is $3/6$, not $4/7$; retaining the original fraction would incorrectly introduce replacement.',result=['6/35','18/35'])
add('Condition on a coarse color history',r'From the same urn, condition on the first two draws having different colors. Find the probability that the third is red. Explain why ignoring the order is valid here.',r'The two retained histories RB and BR each remove one red and one blue. In either case the remaining urn has three red and two blue objects, so the third-red conditional is $3/5$. Total conditional probability over the two histories is a weighted average of two identical rates, hence still $3/5$ regardless of their weights. One may discard the history order only after establishing this equality of remaining compositions. A different condition, such as at least one red, would retain histories with different compositions.',result='3/5')
add('A mixture of remaining urns',r'Draw three times without replacement from four red and three blue objects. Given at least one red in the first two draws, what is the probability the third is red?',r'The conditioning event has mass $1-(3/7)(2/6)=6/7$. The joint target can be calculated by subtracting the excluded history from the third-red marginal. By exchangeability the third-red marginal is $4/7$. The excluded blue-blue-red path has mass $(3/7)(2/6)(4/5)=4/35$. Thus the joint mass is $16/35$, and the conditional is $(16/35)/(6/7)=8/15$. Assuming exactly one red has been removed would give $3/5$ and overlook the retained RR history.',difficulty='Hard',result='8/15')
add('A conditional arrangement erases p',r'Eight independent trials have common success probability $p\in(0,1)$. Given exactly three successes, find the probability that positions one and two are both successes.',r'Every three-success pattern has the same original mass $p^3(1-p)^5$, so the conditional patterns are uniform among $\binom83=56$ possibilities. Fixing successes at positions one and two leaves one success to place in six positions. The ratio is $6/56=3/28$. Equivalently use $(3/8)(2/7)$. The separate conditional marginals are each $3/8$, whose product $9/64$ is different; fixing the total introduced dependence. The restriction on p ensures the conditioning count has positive probability.',result='3/28')
add('A conditional streak count',r'Six independent trials share $p\in(0,1)$. Given exactly three successes, what is the probability they contain a run of three consecutive successes?',r'Conditioning makes the $\binom63=20$ three-success strings equally likely. With exactly three successes, a run of three uses all successes, so its start can be one, two, three, or four. These four patterns are distinct and no pattern contains two different length-three runs. The answer is $4/20=1/5$. Counting starts by multiplication without checking overlap would fail when more successes were allowed. Here the fixed count makes the events disjoint and makes the answer independent of p.',origin='Adapted counting structure: CMU Chapter 2, Exercise 2.24(a); changed trial and success counts',difficulty='Hard',result='1/5')
add('Birthday-type chain with nonuniform labels',r'Three independent label draws take values 1, 2, 3 with probabilities $1/2,1/3,1/6$. Find the probability that all three labels differ.',r'All labels differ precisely when the ordered triple is a permutation of 123. There are six disjoint permutations. Each has mass $(1/2)(1/3)(1/6)=1/36$, so the answer is $1/6$. The usual uniform birthday product would be invalid because the labels are not equiprobable. An alternative chain must condition on which labels have already appeared, not only their count: remaining probability mass depends on their identities. Direct disjoint enumeration avoids an unjustified reduction of the state.',origin='Original nonuniform analogue of CMU Chapter 2, Exercise 2.10',difficulty='Hard',result='1/6')
add('Random eligibility with unequal stages',r'Five objects independently have entry probability $2/3$, and conditional success probability $3/4$ given entry. Find the probability that exactly two objects succeed overall.',r'Each complete object history contributes success with probability $(2/3)(3/4)=1/2$ by the multiplication rule. The independent-history premise makes these five composite indicators mutually independent. A specified two-success pattern therefore has probability $(1/2)^5$, and ten choices of success positions give $10/32=5/16$. Replacing the eligible count by $10/3$ would not even define the original integer-count experiment. Independence of entry and later success within an object was not required; the latter probability was already conditioned on entry.',result='5/16')
add('Total probability needs actual partition weights',r'A source is type one with probability $1/4$ and type two otherwise. Its success rates are $4/5$ and $2/5$, respectively. Find the aggregate rate and the proportion of type-one sources among successes.',r'The two disjoint joint-success masses are $(1/4)(4/5)=1/5$ and $(3/4)(2/5)=3/10$. Their sum is $1/2$, the aggregate success probability. Within the success event, the type-one mass is $(1/5)/(1/2)=2/5$. The unweighted average of the two rates would be $3/5$, which assumes equal source frequencies. The source proportion increases from $1/4$ to $2/5$ after success because the type-one success likelihood is larger.',result=['1/2','2/5'])
add('A conditioned partition uses new weights',r'$D_1,D_2$ are equally likely types. Given $D_1$, observation B has probability $3/4$; given $D_2$, it has probability $1/4$. Within each type A and B are independent, with A rates $2/3$ and $1/3$. Find $P(A\mid B)$.',r'The B mass is $(1/2)(3/4)+(1/2)(1/4)=1/2$. Its conditioned type weights are $3/4$ and $1/4$. Within each type the stated conditional independence keeps the A rates unchanged after B. Therefore the answer is $(3/4)(2/3)+(1/4)(1/3)=7/12$. Original type weights would yield $1/2$ and answer an unconditional question. Without within-type independence, the A rates after B would require additional information.',difficulty='Hard',result='7/12')
add('A countably infinite mixture',r'$P(N=n)=(1-r)r^n$ for $n\ge0$, with $0<r<1$. Conditional on N, N independent checks all pass with per-check probability $q\in(0,1)$. Given that all pass, find the probability that N is positive.',r'The all-pass probability is the convergent sum $\sum_{n\ge0}(1-r)(rq)^n=(1-r)/(1-rq)$. The zero-count case has joint mass $1-r$ because an empty collection satisfies all-pass. Subtracting that case and dividing by the total gives $1-(1-rq)=rq$. More fully the conditional count law is $(1-rq)(rq)^n$. The distinction between all-pass and at least one pass matters: the latter would exclude the zero-count case from the information itself.',difficulty='Hard',result='r*q')
add('Determine whether overlapping cases double-count',r'Events B and C cover the whole space but overlap with positive probability. Is $P(A\mid B)P(B)+P(A\mid C)P(C)$ necessarily $P(A)$? Derive the correction.',r'The displayed sum equals $P(A\cap B)+P(A\cap C)$. Since the union of B and C covers the space, inclusion-exclusion makes this $P(A)+P(A\cap B\cap C)$. Subtract the overlap mass to obtain the correct result. Thus covering is insufficient for the simple total-probability sum; the cases also need to be disjoint in probability, or their target overlap must vanish. For A equal to the whole space, the overcount is exactly $P(B\cap C)$.',difficulty='Hard',result='subtract triple intersection')
add('Simpson reversal in exact fractions',r'A has success rates $9/10,2/5$ in easy and hard cases; B has rates $4/5,3/10$. A receives easy cases with weight $1/10$ and B with weight $9/10$. Calculate the aggregate rates and prove that common weights would prevent this reversal.',r'Weighted addition gives A rate $(1/10)(9/10)+(9/10)(2/5)=9/20$. B rate $(9/10)(4/5)+(1/10)(3/10)=3/4$. A is better within both strata but worse in the aggregate. With a common easy weight w, subtracting the aggregate rates gives $w(1/10)+(1-w)(1/10)=1/10>0$. More generally a common convex combination preserves each within-stratum inequality. Different weights, not a failure of probability laws, produced the reversal.',difficulty='Hard',result=['9/20','3/4'])
add('Disjoint does not normally mean independent',r'Two disjoint events have probabilities a and b. Give a necessary and sufficient condition for independence, including boundary cases.',r'The intersection mass is zero, so product independence is equivalent to $ab=0$. With nonnegative probabilities this holds exactly when a or b is zero. Thus disjoint events of positive probability are dependent: learning one happened rules out the other. A null event is independent of every event by the product definition even though conditioning on that null event is undefined. This boundary distinction is why the factorization definition is more general than the unchanged-conditional slogan.',result='a*b=0')
add('Nested independent events',r'$A\subseteq B$, $P(A)=a$, and $P(B)=b$. Characterize independence. Does the answer change if containment holds only almost surely?',r'The intersection has mass a. Independence requires $a=ab$, or $a(1-b)=0$, giving $a=0$ or $b=1$. The same mass identity holds if the set difference $A\setminus B$ has probability zero, so almost-sure containment gives the same characterization. For a nonnull A and a B with probability strictly below one, nesting forces dependence. If B is certain, observing it adds no probability information and independence holds for every A.',result='a=0 or b=1')
add('Complement closure without conditional division',r'Prove that independence of A and B implies independence of $A^c$ and $B^c$, including zero and one marginal probabilities.',r'Use inclusion-exclusion: $P(A^c\cap B^c)=1-a-b+P(A\cap B)$. Independence replaces the final term by ab. The expression factors as $(1-a)(1-b)=P(A^c)P(B^c)$, which is exactly product independence for the complements. No conditional or division was used, so the proof covers every boundary probability. A proof that divides by $P(A^c)$ would need to separate the case $P(A)=1$ and is unnecessarily fragile.',origin='Adapted proof extension: CMU Chapter 2, Exercise 2.16',result='(1-a)*(1-b)')
add('An event independent of itself',r'Find every possible probability of an event A independent of itself. Then explain how a nonempty event can satisfy the zero case.',r'The intersection of A with itself is A, so independence requires $P(A)=P(A)^2$. Factoring gives $P(A)(1-P(A))=0$, hence probability zero or one. A nonempty null set, such as an individual point under a uniform continuous law, satisfies the zero case. The event need not be empty as a set. This result concerns probability factorization, not logical independence; an event perfectly determines its own truth even when its indicator is almost surely constant.',difficulty='Hard',result=['0','1'])
add('Pairwise independent, not mutually independent',r'Two independent fair bits define $A=\{X=1\}$, $B=\{Y=1\}$, and $C=\{X\ne Y\}$. Verify all pair equations and refute the triple equation.',r'Each event has mass $1/2$. AB retains 11; AC retains 10; BC retains 01. Every pair therefore has mass $1/4$, the product of its marginals. The triple has no outcomes because 11 is not a differing pair, so its mass is zero rather than $1/8$. Given AB, the C conditional is zero although C has marginal $1/2$. All three pair checks are insufficient for a three-way chain factorization into unconditional probabilities.',origin='Adapted counterexample structure: CMU Chapter 2, Exercise 2.18',difficulty='Hard',result=['1/4','0'])
add('Triple factorization is not sufficient',r'On eight equal atoms, let $A=B=\{1,2,3,4\}$ and $C=\{1,5\}$. Check the full triple product and a failed pair condition.',r'The marginal probabilities are $1/2,1/2,1/4$. The triple intersection is just atom one and has mass $1/8$, equal to the product of all three marginals. Yet AB has mass $1/2$, while the product of its marginals is $1/4$. Therefore the events are not mutually independent. A definition checking only the full family loses the subfamily requirements. All three marginals are positive, so the counterexample is not a trick based on a null event.',origin='Constructed counterexample for CMU Chapter 2, Exercise 2.15',difficulty='Hard',result=['1/8','1/2'])
add('Counting independence constraints',r'For five events, how many nontrivial product equalities are required by mutual independence, and how many are checked by pairwise independence alone?',r'There are $2^5-1=31$ nonempty subsets. The five singleton equalities state a probability equals itself and impose no new condition. Thus mutual independence involves $31-5=26$ nontrivial equations. Pairwise independence checks only $\binom52=10$ equations; the other sixteen involve three or more events. Counting constraints does not prove they are logically independent equations, but it precisely describes what the definition requires one to verify or derive.',result=['26','10'])
add('Exactly one heterogeneous success',r'Three mutually independent events have probabilities $1/2,1/3,1/4$. Find the probability that exactly one occurs and the probability that at least one occurs.',r'The three exact-one patterns have masses $(1/2)(2/3)(3/4)=1/4$, $(1/2)(1/3)(3/4)=1/8$, and $(1/2)(2/3)(1/4)=1/12$. They are disjoint, so their sum is $11/24$. None occurs with mass $(1/2)(2/3)(3/4)=1/4$, hence at least one has mass $3/4$. Summing the three marginal success probabilities would double-count simultaneous successes and can exceed one. Mutual independence licenses each pattern product, not naive union addition.',result=['11/24','3/4'])
add('Pairwise information cannot fix an all-failure rate',r'Compare three independent fair bits with the triple $X,Y,X\oplus Y$ generated by two fair bits. In both models the three success events are pairwise independent with probability one half. What are their all-failure probabilities?',r'Three independent fair bits give eight equal states and all failure has mass $1/8$. The two-bit parity construction gives four equal triples: 000, 011, 101, 110. Every coordinate is fair and every pair is independent, but all failure is one of four states and has mass $1/4$. Thus the pairwise data do not determine the joint complement event. The product of three failure probabilities requires mutual independence, including subfamilies beyond pairs.',difficulty='Hard',result=['1/8','1/4'])
add('Selection on equality creates dependence',r'Independent fair bits X,Y are conditioned on equality. Compute the two success marginals, their conditional joint probability, and the factorization error.',r'The retained states 00 and 11 each have conditional mass $1/2$. Hence both success marginals are $1/2$ and their conditional joint is $1/2$. The product of the marginals is $1/4$, leaving a factorization difference of $1/4$. Observing equality did not change either individual success rate; it changed their relationship. Thus unchanged single-event marginals alone do not imply that their joint independence survived selection.',origin='Explicit numerical example for CMU Chapter 2, Exercise 2.19',result=['1/2','1/2','1/4'])
add('Selection on a union creates negative association',r'Independent fair bits X,Y are conditioned on at least one being one. Find the conditional probability that both are one and decide conditional independence.',r'The retained states are 01, 10, 11, all equally likely. Each success marginal is $2/3$, and the joint is $1/3$. Independence would require $4/9$, so the joint is smaller by $1/9$. Once one bit is known to be zero within the retained universe, the other must be one. The negative association comes from the selection rule even though the original coordinate law factorized.',difficulty='Hard',result=['1/3','4/9'])
add('Hidden type makes independent checks dependent',r'Type one and type two each have prior weight one half. Given the type, two checks are independent and have rates $9/10,9/10$ for type one and $1/10,1/10$ for type two. Find the marginal joint and the second-check rate after first success.',r'Weighted joint addition gives $(1/2)(9/10)^2+(1/2)(1/10)^2=41/100$. Each unconditional success marginal is $1/2$. Therefore the checks are not marginally independent, since $41/100\ne1/4$. Dividing the joint by the first-success marginal gives $41/50$. First success changes the relative type weights to $9/10$ and $1/10$; weighting the unchanged within-type second rates by these new weights yields the same result.',difficulty='Hard',result=['41/100','41/50'])
add('Conditional independence in one stratum only',r'A conditioning event C has probability one half. Given C, A and B are independent fair events. Given $C^c$, they are identical fair events. Are they independent given $C^c$? Are they marginally independent?',r'Inside C the four joint cells each have conditional mass $1/4$. Inside its complement only both and neither have conditional mass $1/2$. Thus independence in the complement fails: its joint $1/2$ differs from marginal product $1/4$. Unconditionally each event is fair, but the joint is $(1/2)(1/4)+(1/2)(1/2)=3/8$, also different from $1/4$. Complementing the conditioning event is not the same operation as complementing an independent target event.',origin='Constructed counterexample for CMU Chapter 2, Exercise 2.20',difficulty='Hard',result='3/8')
add('Conditional factorization and its ratio equivalent',r'Assume $P(C)>0$ and $P(B\cap C)>0$. Prove that $P(A\cap B\mid C)=P(A\mid C)P(B\mid C)$ is equivalent to $P(A\mid B\cap C)=P(A\mid C)$.',r'Within the measure conditioned on C, the multiplication rule gives $P(A\cap B\mid C)=P(A\mid B\cap C)P(B\mid C)$. The final factor is positive by the stated intersection condition. Divide by it to obtain the ratio characterization from factorization. Conversely multiply the ratio equality by this factor to recover factorization. If B has zero mass within C, factorization is automatically satisfied but the ratio conditioned on its intersection is undefined, so the positive premise is indispensable.',origin='Independently proved equivalent formulation: CMU Chapter 2, Exercise 2.21',difficulty='Hard',result='equivalent with positive denominator')
add('Opposite hidden-type rates',r'Two equally likely types make A and B conditionally independent. Their respective A rates are $4/5,1/5$ and B rates $1/5,4/5$. Calculate marginal association.',r'Both marginal rates are $1/2$. The joint is $(1/2)(4/5)(1/5)+(1/2)(1/5)(4/5)=4/25$. Subtracting marginal product $1/4$ gives $-9/100$, so the marginal association is negative. The two-stratum identity yields the same value: $(1/4)(3/5)(-3/5)=-9/100$. Conditional independence is compatible with either sign of marginal association because the hidden type can move the two success rates together or in opposite directions.',difficulty='Hard',result=['4/25','-9/100'])
add('When a mixture remains independent',r'In two strata with nonzero weights w and $1-w$, A and B are conditionally independent, with rates $u_1,u_2$ and $v_1,v_2$. Give the exact criterion for marginal independence.',r'Expand the joint-minus-product expression. It simplifies to $w(1-w)(u_1-u_2)(v_1-v_2)$. Because the two weights are positive, the difference is zero precisely when $u_1=u_2$ or $v_1=v_2$. Thus at least one target rate must be constant across the two strata. This is a two-stratum result; with three or more strata, positive and negative covariance contributions can cancel even if neither list is constant.',difficulty='Hard',result='one rate constant')
add('A truthful report has two different answers',r'Two independent fair sensors are active or inactive. Compare the probability both are active given a report under two protocols: report whenever at least one is active; or choose one sensor uniformly and report if it is active.',r'The first message has probability $3/4$ and its joint probability with both active is $1/4$, yielding $1/3$. In the second protocol, the single-active states report with probability $1/2$ while the both-active state reports with probability one. The message mass is $(1/4)(1/2)+(1/4)(1/2)+1/4=1/2$, giving answer $1/2$. Both protocols tell the truth, but the retained state weights differ. The reporting process must be included in the model.',origin='Original protocol analogue motivated by Berkeley STAT 134 Lecture 2, PDF page 12',difficulty='Hard',result=['1/3','1/2'])
add('Two-sided cards and face multiplicity',r'Cards RR, RB, BB are selected uniformly and then shown on a uniformly chosen face. Given a red face, find the probability the hidden face is red. Contrast a procedure that selects uniformly among cards containing red and deliberately shows red.',r'The first procedure has six equally likely card-face outcomes. Three show red, two of them on RR. The hidden face is therefore red with probability $2/3$. In the second procedure there are two equally likely card choices RR and RB, each guaranteed to show red. The hidden-red probability is $1/2$. Counting retained card types without their observation likelihoods produces the wrong answer for the first experiment because RR has twice as many red faces.',origin='Fully specified adaptation: Berkeley STAT 134 Lecture 2, PDF page 11',result=['2/3','1/2'])
add('A biased informed host',r'The prize is uniformly behind one of three doors and you chose door one. An informed host always reveals an unchosen empty door. When the prize is at door one, the host opens door three with probability t. Given that door three is opened, find the switching success probability and its feasible range.',r'The joint weights for prize at one, two, three and opening door three are $t/3,1/3,0$. The observation mass is $(1+t)/3$, positive for every $t\in[0,1]$. Switching to door two succeeds with conditional probability $1/(1+t)$, ranging from one when t is zero to one half when t is one. At fair tie-breaking t equals one half, the result is two thirds. Aggregate switching before seeing a named opened door still succeeds with probability two thirds; the named-message conditional can depend on t.',origin='Original tie-breaking extension of CMU Chapter 2, Exercise 2.22',difficulty='Hard',result='1/(1+t)')
add('A host who does not know the prize',r'After choosing door one, a host independently opens door two or three uniformly without inspecting the prize. Given that the opened door is empty, should switching to the remaining closed door have probability two thirds of winning?',r'If the prize is behind door one, the host reveals an empty door with probability one, contributing mass $1/3$. If the prize is behind either other door, the host reveals empty with probability one half, each contributing $1/6$. The empty-reveal event has mass $2/3$. Given it, the initial door is winning with probability $(1/3)/(2/3)=1/2$. Switching succeeds exactly in the two other retained cases, with total conditional probability one half. The informed always-reveal calculation answers a different protocol.',difficulty='Hard',result='1/2')
add('Shared-edge paths are dependent',r'Three independent edges E,F,G each work with probability p. Paths EF and EG connect a system. Find the reliability and quantify the error from treating the paths as independent.',r'The union of path events has mass $p^2+p^2-p^3=2p^2-p^3$, since their intersection requires all three edges. The false independent-path formula would use joint mass $p^4$ and give $2p^2-p^4$. Its excess is $p^3-p^4=p^3(1-p)$, positive for interior p. At p one half, correct reliability is $3/8$ and the false value is $7/16$. Independent components do not make paths sharing a component independent.',difficulty='Hard',result=['3/8','7/16'])
add('Bridge reliability by conditioning',r'Use the five-edge bridge network described in the lesson, with all edge states independent and working probability p. Derive its reliability and evaluate at p one half.',r'Condition on the bridge. With it failed, the two disjoint series paths give $2p^2-p^4$. With it working, the network needs at least one of two source edges and at least one of two destination edges; their disjoint coordinate blocks give $(2p-p^2)^2$. Total probability weights these by $1-p$ and p. At one half the case reliabilities are $7/16,9/16$ and the average is $1/2$. This reduction avoids treating overlapping full-network paths as independent and passes both zero and one endpoint checks.',origin='Original explicit network instance motivated by Berkeley STAT 134 Lecture 3, PDF pages 5–7; board-only derivations not used',difficulty='Hard',result='1/2')
add('Edge-disjoint two-hop alternatives',r'Eight edge-disjoint two-hop paths each use two independent edges with working probability p, and all sixteen edge states are mutually independent. Derive the system reliability. Why is $8p^2$ usually wrong?',r'Each path works with probability $p^2$. Because their edge coordinate blocks are disjoint under a mutually independent primitive model, the path events are mutually independent. All paths fail with probability $(1-p^2)^8$, so system reliability is $1-(1-p^2)^8$. Adding path probabilities would overcount states with several working paths. The sum $8p^2$ is only a union bound and can exceed one; it is exact here only at p zero. At p one the reliability must be one rather than eight.',origin='Independently explained model: CMU Chapter 2, Section 2.4 network discussion',result='1-(1-p*p)^8')
add('Conditional independence is not supplied by equal rates',r'Two bits have joint masses $P(00)=P(11)=3/8$ and $P(01)=P(10)=1/8$. Each bit is fair. Find the chance the second is one given the first is one and quantify the departure from independence.',r'The first-one mass is $1/2$, and the both-one mass is $3/8$. The conditional is therefore $3/4$, not the marginal one half. Product independence would require the both-one mass to be $1/4$, whereas its excess is $1/8$. Fairness describes each marginal separately and places no requirement on the joint arrangement. A valid joint-table calculation, rather than equal rates or symmetry of labels, settles the independence question.',result='3/4')
add('Conditional geometry on a triangle',r'For a uniform point on the unit square, find $P(X\le1/2\mid X+Y\le1)$ and explain why a one-dimensional length ratio is invalid.',r'The condition is a triangle of area one half. Its portion with X at most one half has area $\int_0^{1/2}(1-x)dx=3/8$. Dividing the areas gives $3/4$. The horizontal projection has length one, but the vertical cross-section decreases with x, so equal horizontal lengths do not represent equal conditional masses. The conditioned density is uniform over area in the triangle, not uniform over its horizontal projection.',difficulty='Hard',result='3/4')
add('An exact observation requires a density model',r'The joint density is two on $0<x<y<1$ and zero elsewhere. For $0<y<1$, find the conditional density of X given Y=y, and $P(X\le y/3\mid Y=y)$.',r'Integrate the joint density over x to obtain marginal density $f_Y(y)=2y$. The conditional density version is $2/(2y)=1/y$ on $0<x<y$ and zero outside. It integrates to one. Integrating from zero to y/3 gives probability one third. This uses a density ratio at a point with positive marginal density; it does not divide by the event probability $P(Y=y)$, which is zero. Boundary values require a stated version rather than this interior division.',origin='Original smooth-density example motivated by Oxford Part B Applied Probability, Section 2.2',difficulty='Hard',result='1/3')
add('A shrinking strip calculation',r'For the preceding triangular density, fix $0<y<1$ and $0<\varepsilon<1-y$. Calculate $P(X\le y/2\mid y\le Y\le y+\varepsilon)$ and its limit as the strip shrinks.',r'The strip mass is $\int_y^{y+\varepsilon}2u\,du=2y\varepsilon+\varepsilon^2$. The target rectangle inside it has width y/2 and height epsilon, entirely inside the triangle; its mass is $y\varepsilon$. Their ratio simplifies to $y/(2y+\varepsilon)$ and tends to one half. Each finite strip has positive mass, so its ratio is defined. The limit supplies the natural continuous conditional version in this regular model; the zero-mass line itself never becomes a valid elementary denominator.',difficulty='Hard',result='y/(2*y+epsilon)')
add('How little does pairwise data identify?',r'Three fair events are pairwise independent. Let t be their triple-intersection probability. Determine every feasible t and construct the full eight-cell table.',r'The 111 cell is t. Each two-success-only cell is $1/4-t$ because each pair intersection is one quarter. Each one-success-only cell is t after subtracting those cells from its one-half marginal. Normalization leaves the 000 cell $1/4-t$. All eight cells are nonnegative exactly when $0\le t\le1/4$. They sum to one and recover every specified pair, so this interval is sharp. Mutual independence selects $t=1/8$, but the pairwise premises alone allow the entire interval.',difficulty='Hard',result=['0','1/4'])
add('Conditional constraints identify a hidden parameter',r'$P(B)=b$, $P(A\mid B)=u$, and $P(A\mid B^c)=v$, with $0<b<1$. Express the determinant of the two-event joint table and characterize its zero set.',r'The cells in row-column order are $bu,(1-b)v,b(1-u),(1-b)(1-v)$. The determinant, both times neither minus A-only times B-only, is $b(1-b)[u(1-v)-v(1-u)]=b(1-b)(u-v)$. It is also the joint-minus-marginal-product quantity $P(A\cap B)-P(A)P(B)$. With nonzero stratum weights, independence therefore holds exactly when u equals v. The calculation links an algebraic matrix criterion to the statement that knowing B leaves the A rate unchanged.',difficulty='Hard',result='b*(1-b)*(u-v)')

assert len(questions)==56,len(questions)
Path(__file__).with_name('s_conditional-questions.json').write_text(json.dumps(questions,indent=2)+'\n',encoding='utf-8')
print('Authored 56 distinct calculation, proof, protocol and counterexample problems.')
